CREATE TABLE IF NOT EXISTS "LandPlots" (
    "Id" INTEGER NOT NULL CONSTRAINT "PK_LandPlots" PRIMARY KEY AUTOINCREMENT,
    "CadastralNumber" TEXT NOT NULL,
    "Title" TEXT NOT NULL,
    "Location" TEXT NOT NULL,
    "AreaHectares" REAL NOT NULL,
    "Purpose" TEXT NOT NULL,
    "PriceUsd" TEXT NOT NULL,
    "Description" TEXT NOT NULL,
    "OwnershipDocNumber" TEXT NOT NULL,
    "SellerBankIban" TEXT NOT NULL,
    "Status" INTEGER NOT NULL,
    "SellerId" INTEGER NOT NULL,
    "AssignedRealtorId" INTEGER NULL,
    "CreatedAt" TEXT NOT NULL,
    CONSTRAINT "FK_LandPlots_Users_AssignedRealtorId" FOREIGN KEY ("AssignedRealtorId") REFERENCES "Users" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_LandPlots_Users_SellerId" FOREIGN KEY ("SellerId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);
