INSERT INTO LegalConclusions VALUES(1,'ЮВ-2026-001',1,2,1,1,1,1,1,'Низький (Чисто)','ВТ-ДЗК-2026-0001','За даними ДЗК та ДРРП ділянка у с. Лісники зареєстрована належним чином. Координати поворотних точок меж узгоджені, обтяжень не виявлено.',1,'2026-11-04 13:05:23.631097');
INSERT INTO LegalConclusions VALUES(2,'ЮВ-2026-002',2,2,1,1,1,1,1,'Низький (Чисто)','ВТ-ДЗК-2026-0002','Перевірку у ДЗК та ДРРП пройдено успішно. Судових арештів, іпотек та земельних сервітутів не зареєстровано.',1,'2026-11-05 13:05:23.631234');
INSERT INTO LegalConclusions VALUES(3,'ЮВ-2026-0003',3,2,1,1,1,1,1,'Низький (Чисто)','ВТ-ДЗК-2026-0003','Повну перевірку у ДЗК та ДРРП пройдено успішно. Обтяжень, арештів та сервітутів не виявлено.',1,'2026-11-09 13:05:23.584547');
INSERT INTO LegalConclusions VALUES(4,'ЮВ-2026-0004',4,6,0,0,1,1,1,'Високий (Виявлено арешт / обтяження)','ВТ-ДЗК-2026-0004','Виявлено обтяження у ДРРП: судова заборона відчуження. Відмовлено у внесенні до каталогу.',0,'2026-11-10 13:05:23.584548');
