CREATE TABLE IF NOT EXISTS "Payments" (
    "Id" INTEGER NOT NULL CONSTRAINT "PK_Payments" PRIMARY KEY AUTOINCREMENT,
    "SaleDealId" INTEGER NOT NULL,
    "ReceiptNumber" TEXT NOT NULL,
    "InvoiceNumber" TEXT NOT NULL,
    "AmountUsd" TEXT NOT NULL,
    "PaymentDate" TEXT NOT NULL,
    "PaymentType" TEXT NOT NULL,
    "SenderIban" TEXT NOT NULL,
    "RecipientIban" TEXT NOT NULL,
    "PaymentReference" TEXT NOT NULL,
    "Status" INTEGER NOT NULL,
    "IsPaid" INTEGER NOT NULL,
    "SubmittedAt" TEXT NULL,
    "VerifiedAt" TEXT NULL,
    "VerifiedByUserId" INTEGER NULL,
    "VerificationNotes" TEXT NOT NULL,
    CONSTRAINT "FK_Payments_SaleDeals_SaleDealId" FOREIGN KEY ("SaleDealId") REFERENCES "SaleDeals" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Payments_Users_VerifiedByUserId" FOREIGN KEY ("VerifiedByUserId") REFERENCES "Users" ("Id")
);
